class Solution {
public:
    TreeNode* createBinaryTree(vector<vector<int>>& descriptions) {
        unordered_map<int, TreeNode*> nodes;
        unordered_set<int> children;
        for (const auto& d : descriptions) {
            int p = d[0], c = d[1], isLeft = d[2];
            if (!nodes.count(p)) nodes[p] = new TreeNode(p);
            if (!nodes.count(c)) nodes[c] = new TreeNode(c);
            if (isLeft) nodes[p]->left = nodes[c];
            else nodes[p]->right = nodes[c];
            children.insert(c);
        }
        for (const auto& pair : nodes) {
            if (!children.count(pair.first)) {
                return pair.second;
            }
        }
        return nullptr;
    }
};

class Solution {
    public TreeNode createBinaryTree(int[][] descriptions) {
        Map<Integer, TreeNode> nodes = new HashMap<>();
        Set<Integer> children = new HashSet<>();
        for (int[] d : descriptions) {
            int p = d[0], c = d[1], isLeft = d[2];
            nodes.putIfAbsent(p, new TreeNode(p));
            nodes.putIfAbsent(c, new TreeNode(c));
            if (isLeft == 1) {
                nodes.get(p).left = nodes.get(c);
            } else {
                nodes.get(p).right = nodes.get(c);
            }
            children.add(c);
        }
        for (int p : nodes.keySet()) {
            if (!children.contains(p)) {
                return nodes.get(p);
            }
        }
        return null;
    }
}

/**
 * @param {number[][]} descriptions
